export const getStoreUserSignatureUrl = (params: StoreUserSignatureParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/auth/user-signatures?${stringifiedParams}` : `/api/v1/auth/user-signatures`
}

/**
 * @summary Upload or replace the authenticated user's signature image (multipart; password-verified — 3 wrong attempts block saves for 15 minutes)
 */
export const storeUserSignature = async (params: StoreUserSignatureParams,
    storeUserSignatureBody?: StoreUserSignatureBody, options?: RequestInit): Promise<storeUserSignatureResponse> => {
    const formData = new FormData();
if(storeUserSignatureBody?.data !== undefined) {
 formData.append(`data`, storeUserSignatureBody.data);
 }

  return syncroFetch<storeUserSignatureResponse>(getStoreUserSignatureUrl(params),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}




